const fs = require('fs');
const readline = require('readline');

const logFile = 'C:\\Users\\computer\\.gemini\\antigravity\\brain\\572b5ef2-df3a-452d-b484-217992cd5adc\\.system_generated\\logs\\transcript_full.jsonl';

const rl = readline.createInterface({
  input: fs.createReadStream(logFile),
  crlfDelay: Infinity
});

let lineNum = 0;
rl.on('line', (line) => {
  lineNum++;
  if (line.includes('garcom.html') && (line.includes('write_to_file') || line.includes('replace_file_content'))) {
    console.log(`Line ${lineNum}: length=${line.length}, has view-bill? ${line.includes('view-bill')}, has view-details? ${line.includes('view-details')}`);
  }
});
